// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _test(uint256 _initial, uint256 _changed) internal {
        vm.assume(_initial != _changed);
        try c.SetMinSum(_initial) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(_changed) {} catch { return; }
        assertTrue(c.MinSum() == _initial);
    }

    function testFuzz_test(uint256 _initial, uint256 _changed) public {
        _test(_initial, _changed);
    }

    receive() external payable {}
}
